CREATE OR REPLACE FUNCTION private.dispatch_push_notice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare cfg record;
begin
 select secret,webhook_url into cfg from private.push_config where id=1;
 perform net.http_post(url:=cfg.webhook_url,body:=jsonb_build_object('notification_id',new.id),headers:=jsonb_build_object('Content-Type','application/json','x-push-secret',cfg.secret),timeout_milliseconds:=8000);
 return new;
end $function$
